m=funcs;
f=add(a:i64;b:i64):i64{
  <a+b
};
f=main():i64{
  <add(3;4)
};

m=chain;
f=double(x:i64):i64{
  <x*2
};
f=inc(x:i64):i64{
  <x+1
};
f=main():i64{
  let v=double(inc(5));
  <v
};

m=multi;
f=square(n:i64):i64{
  <n*n
};
f=negate(n:i64):i64{
  <0-n
};
f=abs_diff(a:i64;b:i64):i64{
  if(a>b){
    <a-b
  }el{
    <b-a
  }
};
f=main():i64{
  let x=square(3);
  let y=negate(4);
  <abs_diff(x;y)
};

m=branch;
f=main():i64{
  let x=5;
  if(x>3){
    <1
  }el{
    <0
  }
};

m=grade;
f=grade(score:i64):i64{
  if(score>89){
    <4
  }el{
    if(score>79){
      <3
    }el{
      if(score>69){
        <2
      }el{
        <1
      }
    }
  }
};
f=main():i64{
  <grade(85)
};

m=loops;
f=main():i64{
  let sum=mut.0;
  lp(let i=1;i<6;i=i+1){
    sum=sum+i
  };
  <sum
};

m=arrsum;
f=sum(arr:[i64]):i64{
  let acc=mut.0;
  lp(let i=0;i<arr.len;i=i+1){
    acc=acc+arr[i]
  };
  <acc
};
f=main():i64{
  let nums=[10;20;30];
  <sum(nums)
};

m=arrays;
f=get(arr:[i64];i:i64):i64{
  <arr[i]
};
f=main():i64{
  let a=[10;20;30;40;50];
  let first=a[0];
  let last=a[4];
  <first+last
};

m=structs;
t=Point{x:i64;y:i64};
f=main():i64{
  let p=Point{x:3;y:4};
  <p.x+p.y
};

m=vec;
t=Vec2{x:i64;y:i64};
f=add(a:Vec2;b:Vec2):Vec2{
  <Vec2{x:a.x+b.x;y:a.y+b.y}
};
f=main():i64{
  let a=Vec2{x:3;y:4};
  let b=Vec2{x:10;y:20};
  let c=add(a;b);
  <c.x+c.y
};

