i=str:std.str;
f=main():i64{
  let a="hello";
  let b=" world";
  let c=str.concat(a;b);
  let n=str.len(c);
  <n
};

m=logic;
f=both(a:bool;b:bool):bool{
  if(a){
    if(b){
      <true
    }el{
      <false
    }
  }el{
    <false
  }
};
f=main():i64{
  if(both(true;true)){
    <1
  }el{
    <0
  }
};

m=nested;
f=main():i64{
  let a=3;
  let b=7;
  let c=a*b+a-b;
  let d=c*2+a;
  let e=d-c+b*a;
  <e
};

