m=errs;
t=FetchErr{
  NotFound:i64;
  Timeout:Str
};
f=fetch(id:i64):Str!FetchErr{
  if(id<0){
    <FetchErr.NotFound(id)
  }el{
    <"found"
  }
};
f=main():i64{
  <0
};

m=matching;
t=Shape{
  Circle:i64;
  Square:i64
};
f=area(s:Shape):i64{
  <s|{
    Circle:r r*r*3;
    Square:side side*side
  }
};
f=main():i64{
  let c=Shape.Circle(5);
  <area(c)
};

m=mutable;
f=main():i64{
  let x=mut.1;
  x=x+10;
  x=x*2;
  <x
};

m=casting;
f=main():i64{
  let narrow=42;
  let wide=narrow as i64;
  <wide
};

m=breaking;
f=find_first_gt(arr:[i64];threshold:i64):i64{
  let result=mut.0-1;
  lp(let i=0;i<arr.len;i=i+1){
    if(arr[i]>threshold){
      result=arr[i];
      br
    }el{
      result=result
    }
  };
  <result
};
f=main():i64{
  let nums=[3;7;2;9;1];
  <find_first_gt(nums;5)
};

m=returns;
f=classify(n:i64):i64{
  if(n>0){
    <1
  }el{
    if(n<0){
      <0-1
    }el{
      <0
    }
  }
};
f=main():i64{
  let a=classify(5);
  let b=classify(0-3);
  let c=classify(0);
  <a+b+c
};

m=arrop;
f=max(arr:[i64]):i64{
  let m=mut.arr[0];
  lp(let i=1;i<arr.len;i=i+1){
    if(arr[i]>m){
      m=arr[i]
    }el{
      m=m
    }
  };
  <m
};
f=main():i64{
  let data=[4;9;2;7;1;8];
  <max(data)
};

m=recurse;
f=factorial(n:i64):i64{
  if(n<2){
    <1
  }el{
    <n*factorial(n-1)
  }
};
f=main():i64{
  <factorial(5)
};

m=fib;
f=fib(n:i64):i64{
  if(n<2){
    <n
  }el{
    <fib(n-1)+fib(n-2)
  }
};
f=main():i64{
  <fib(10)
};

m=voids;
f=greet():void{
  let x=42;
};
f=main():i64{
  greet();
  <0
};

m=stats;
t=Stats{min:i64;max:i64;sum:i64};
f=compute(arr:[i64]):Stats{
  let mn=mut.arr[0];
  let mx=mut.arr[0];
  let sm=mut.arr[0];
  lp(let i=1;i<arr.len;i=i+1){
    if(arr[i]<mn){
      mn=arr[i]
    }el{
      mn=mn
    };
    if(arr[i]>mx){
      mx=arr[i]
    }el{
      mx=mx
    };
    sm=sm+arr[i]
  };
  <Stats{min:mn;max:mx;sum:sm}
};
f=main():i64{
  let data=[5;1;8;3;9;2];
  let s=compute(data);
  <s.sum
};
